pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = (step_index as f64 / total_items as f64).powf(1.5);
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let score = -stream_progress * residual_ratio.powi(2) + 0.5 * stream_progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, _bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Reward bins that are close to being full
    if bin_residual < 15 {
        score += (15 - bin_residual) as f64;
    }

    // Penalize creating new bins too early or late in the sequence
    let time_index = step_index as f64 / total_items as f64;
    if time_index < 0.25 || time_index > 0.75 {
        score -= (time_index.min(1.0) - 0.5).abs() * open_bins_count as f64 * 3.0;
    }

    // Reward bins that can fit the next item
    if fitting_bins_count > 0 {
        score += (fitting_bins_count * 2) as f64;
    }

    // Penalize creating new bins with small residual space
    if post_residual < 20 && open_bins_count == 1 {
        score -= post_residual as f64 / 10.0;
    }

    // Reward using bins with high residual space
    if mean_residual > 50.0 {
        score += (mean_residual - 50.0) / 10.0;
    }

    // Penalize creating new bins when the next item is large
    if next_item_size > 70 && open_bins_count == 1 {
        score -= next_item_size as f64 / 15.0;
    }

    // Reward using bins with low residual space for small items
    if item_size < 20 && post_residual < 30 {
        score += (30 - post_residual) as f64;
    }

    score
}

